mapper.update:
UPDATE apr31_appr_step_group_member
   SET apr31_step_type_cd = #{stepTypeCode},
       apr31_seq          = #{seq},
       apr31_note         = #{note},
       apr31_step_emp_id  = #{stepEmpId}
 WHERE apr31_appr_step_group_member_id = #{id}
   AND apr31_appr_step_group_id        = #{apprStepGroupId}

mapper.delete:
DELETE FROM apr31_appr_step_group_member
 WHERE apr31_appr_step_group_member_id = #{id}
   AND apr31_appr_step_group_id IN (SELECT apr30_appr_step_group_id FROM apr30_appr_step_group WHERE apr30_company_id = #{companyId})
